package cn.balltv.portal;
import android.graphics.*;import android.media.MediaMetadataRetriever;import android.widget.*;import android.util.LruCache;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Static card images: bounded downloads, two workers, small decoded bitmaps. */
final class Thumbnails {
 final Semaphore decoder=VideoEvidence.DECODER;final ThreadLocal<Long> budget=new ThreadLocal<Long>();final MainActivity owner;final ExecutorService workers=BackgroundWork.pool(2,"previews");final LruCache<String,Bitmap> memory=new LruCache<String,Bitmap>(Ui.LEAN?16:32);final Map<String,Long> cachedAt=new HashMap<String,Long>();final Set<String> pending=new HashSet<String>();final Map<String,Long> failed=new HashMap<String,Long>();final Map<String,List<ImageView>> waiting=new HashMap<String,List<ImageView>>();final Map<ImageView,Events.Group> bound=new WeakHashMap<ImageView,Events.Group>();final ThreadLocal<Boolean> decoderBusy=new ThreadLocal<Boolean>();boolean closed;
 Thumbnails(MainActivity a){owner=a;File[] files=a.getCacheDir().listFiles((dir,name)->name.startsWith("thumb10safe-")||name.startsWith("thumb14-")||name.startsWith("thumb15-"));if(files!=null){Arrays.sort(files,(x,y)->Long.compare(y.lastModified(),x.lastModified()));for(int i=64;i<files.length;i++)files[i].delete();}}
 void bind(ImageView image,Events.Group group){bound.put(image,group);String key=PreviewFrames.key(group);image.setTag(key);Bitmap bitmap=memory.get(key);if(bitmap!=null){if(!(image.getDrawable() instanceof android.graphics.drawable.BitmapDrawable)||((android.graphics.drawable.BitmapDrawable)image.getDrawable()).getBitmap()!=bitmap)image.setImageBitmap(bitmap);if(cachedAt.containsKey(key)&&System.currentTimeMillis()-cachedAt.get(key)<600000)return;}if(image.getWidth()==0){image.addOnLayoutChangeListener(new android.view.View.OnLayoutChangeListener(){public void onLayoutChange(android.view.View v,int l,int t,int r,int b,int ol,int ot,int or,int ob){if(r>l){v.removeOnLayoutChangeListener(this);if(!closed&&owner.foreground)bind(image,group);}}});return;}android.graphics.Rect visible=new android.graphics.Rect();if(!image.getGlobalVisibleRect(visible)||visible.height()<12||!owner.foreground)return;List<ImageView> list=waiting.get(key);if(list==null){list=new ArrayList<ImageView>();waiting.put(key,list);}if(!list.contains(image))list.add(image);if(failed.containsKey(key))for(Feeds.Match member:group.members){StreamHealth.Good good=StreamHealth.good(member,System.currentTimeMillis());if(good!=null&&good.at>failed.get(key)){failed.remove(key);break;}}if(pending.contains(key)||failed.containsKey(key)&&System.currentTimeMillis()-failed.get(key)<(Ui.LEAN?20000:20000))return;Long failure=failed.get(key);if(failure!=null)for(Feeds.Match member:group.members){StreamHealth.Good good=StreamHealth.good(member,System.currentTimeMillis());if(good!=null&&good.at>failure){failed.remove(key);break;}}pending.add(key);final boolean library=!owner.view.equals("live");workers.execute(()->{Bitmap result=null;long at=System.currentTimeMillis();boolean attempted=false;try{decoderBusy.set(false);budget.set(System.nanoTime()+11000000000L);if(owner.foreground){File file=PreviewFrames.file(owner,group);if(file.exists()&&System.currentTimeMillis()-file.lastModified()<(library?7*86400000L:86400000L)){BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.ARGB_8888;result=BitmapFactory.decodeFile(file.toString(),options);at=file.lastModified();}if(result==null&&owner.quietForImages()&&!(group.lead().status.equals("upcoming")&&group.start>System.currentTimeMillis())){attempted=true;result=load(group);at=System.currentTimeMillis();if(result!=null)PreviewFrames.store(owner,group,result,group.lead().sport);}}}catch(Exception ignored){}final Bitmap ready=result;final long captured=System.currentTimeMillis();final boolean tried=attempted&&!Boolean.TRUE.equals(decoderBusy.get());owner.runOnUiThread(()->{android.util.Log.d("BallTVCover",(ready==null?"miss":"ready")+" "+group.lead().sport);pending.remove(key);List<ImageView> views=waiting.remove(key);if(closed)return;if(ready!=null){memory.put(key,ready);cachedAt.put(key,captured);if(views!=null)for(ImageView v:views)if(key.equals(v.getTag())){v.setImageBitmap(ready);}}else if(tried&&owner.quietForImages())failed.put(key,System.currentTimeMillis());});});}
 Bitmap load(Events.Group group)throws Exception{
 ArrayList<Feeds.Match> choices=SourcePreferences.filter(owner,group.members);Collections.sort(choices,(x,y)->Boolean.compare(StreamHealth.good(x,System.currentTimeMillis())==null,StreamHealth.good(y,System.currentTimeMillis())==null));
 long full=budget.get();budget.set(Math.min(full,System.nanoTime()+2500000000L));Set<String> posters=new HashSet<String>();int attempts=0;
 for(Feeds.Match m:choices){if(owner.view.equals("live"))break;if(!canLoad())break;if(!posterUrl(m.cover)||!posters.add(m.cover))continue;if(attempts++>=4)break;try{Bitmap poster=decode(download(m.cover,Feeds.base(m.source)+"/",900000));if(poster!=null){if(PreviewFrames.acceptable(poster,m.sport))return poster;poster.recycle();}}catch(Exception ignored){}}
 budget.set(full);Set<String> urls=new HashSet<String>();attempts=0;
 for(Feeds.Match m:choices){if(!canLoad())return null;StreamHealth.Good good=StreamHealth.good(m,System.currentTimeMillis());if(good==null||!urls.add(good.url))continue;android.util.Log.d("BallTVCover","media "+m.sport+" "+(good.fingerprint.equals("flv")?"flv":"hls"));if(attempts++>=2)break;try{String ref=good.line.referer.isEmpty()?Feeds.base(m.source)+"/":good.line.referer;byte[] shared=ProbeFrames.take(StreamHealth.key(m),System.currentTimeMillis());if(shared!=null){try{Bitmap evidence=good.fingerprint.equals("flv")?acceptedFlv(shared,m.sport):fromSample(shared,good.initUrl,ref,m.sport);if(evidence!=null)return evidence;}catch(Exception ignored){}}Bitmap result=good.fingerprint.equals("flv")?acceptedFlv(download(good.url,ref,2500000),m.sport):!good.previewUrl.isEmpty()&&System.currentTimeMillis()-good.at<30000?segment(good.previewUrl,good.initUrl,ref,m.sport):frame(good.url,ref,0,m.sport,m.kind.equals("replay"));if(result!=null)return result;}catch(Exception ignored){android.util.Log.d("BallTVCover","media miss "+ignored.getClass().getSimpleName());}if(canLoad()){try{VideoEvidence.Result evidence=VideoEvidence.capture(owner,good.url,good.line.referer.isEmpty()?Feeds.base(m.source)+"/":good.line.referer,m.sport,()->!closed&&owner.quietForImages(),6000);if(!evidence.attempted)decoderBusy.set(true);if(evidence.cover!=null)return evidence.cover;}catch(Exception ignored){}}}
 if(!owner.view.equals("live")&&canLoad())for(Feeds.Match m:choices)try{ArrayList<Feeds.Line> lines=Feeds.lines(m);if(lines.isEmpty())continue;Feeds.Line line=lines.get(0);return frame(Feeds.resolve(m,line),line.referer.isEmpty()?Feeds.base(m.source)+"/":line.referer,0,m.sport,m.kind.equals("replay"));}catch(Exception ignored){break;}
 return null;
 }
 boolean canLoad(){Long end=budget.get();return !closed&&owner.quietForImages()&&(end==null||System.nanoTime()<end);}
 static boolean posterUrl(String url){try{return HttpData.publicUrl(url)&&new URL(url).getPath().length()>1;}catch(Exception e){return false;}}
 Bitmap fromSample(byte[] bytes,String init,String ref,String sport)throws Exception{if(!init.isEmpty()){byte[] prefix=download(init,ref,250000),joined=new byte[prefix.length+bytes.length];System.arraycopy(prefix,0,joined,0,prefix.length);System.arraycopy(bytes,0,joined,prefix.length,bytes.length);bytes=joined;}Bitmap image=extract(bytes,sport);if(image!=null&&!PreviewFrames.frameAvailable(image)){image.recycle();return null;}return image;}
 Bitmap segment(String url,String init,String ref,String sport)throws Exception{byte[] prefix=init.isEmpty()?new byte[0]:download(init,ref,250000),media=download(url,ref,3200000);byte[] bytes=media;if(prefix.length>0){bytes=new byte[prefix.length+media.length];System.arraycopy(prefix,0,bytes,0,prefix.length);System.arraycopy(media,0,bytes,prefix.length,media.length);}Bitmap result=extract(bytes,sport);if(result!=null&&!PreviewFrames.frameAvailable(result)){android.util.Log.d("BallTVCover","frame rejected "+sport);result.recycle();return null;}return result;}
 Bitmap acceptedFlv(byte[] bytes,String sport)throws Exception{byte[] mp4=FlvPreview.mp4(bytes);if(mp4==null)return null;Bitmap result=extract(mp4,sport);if(result!=null&&!PreviewFrames.frameAvailable(result)){result.recycle();return null;}return result;}
 Bitmap frame(String url,String referer,int depth,String sport,boolean replay)throws Exception{
  if(depth>2)return null;
  if(url.toLowerCase(Locale.ROOT).matches(".*\\.(flv|mp4)(\\?.*)?")){byte[] bytes=download(url,referer,2500000);Bitmap image=extract(bytes.length>3&&bytes[0]=='F'&&bytes[1]=='L'&&bytes[2]=='V'?FlvPreview.mp4(bytes):bytes,sport);if(image!=null&&!PreviewFrames.frameAvailable(image)){image.recycle();image=null;}return image;}String text=new String(download(url,referer,180000),"UTF-8");if(!replay&&text.contains("#EXT-X-ENDLIST"))return null;PreviewPlan plan=PreviewPlan.parse(url,text);if(plan==null)return null;return plan.master?frame(plan.media,referer,depth+1,sport,replay):segment(plan.media,plan.init,referer,sport);
 }
 Bitmap extract(byte[] bytes,String sport)throws Exception{if(bytes==null||!canLoad()||!decoder.tryAcquire(500,TimeUnit.MILLISECONDS))return null;File clip=null;MediaMetadataRetriever retriever=null;try{clip=File.createTempFile("frame-",".ts",owner.getCacheDir());retriever=new MediaMetadataRetriever();try(FileOutputStream out=new FileOutputStream(clip)){out.write(bytes);}retriever.setDataSource(clip.toString());Bitmap image=android.os.Build.VERSION.SDK_INT>=27?retriever.getScaledFrameAtTime(0,MediaMetadataRetriever.OPTION_CLOSEST_SYNC,320,180):retriever.getFrameAtTime(0,MediaMetadataRetriever.OPTION_CLOSEST_SYNC);if(image==null)image=retriever.getFrameAtTime(1000000,MediaMetadataRetriever.OPTION_CLOSEST_SYNC);Bitmap first=scale(image);return first;}finally{try{if(retriever!=null)retriever.release();}finally{if(clip!=null)clip.delete();decoder.release();}}}
 byte[] download(String url,String referer,int max)throws Exception{for(int redirect=0;redirect<4;redirect++){if(!HttpData.publicUrl(url)||!canLoad())throw new IOException();HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(1500);c.setReadTimeout(1500);c.setRequestProperty("Accept-Encoding","identity");c.setRequestProperty("User-Agent",Feeds.UA);c.setRequestProperty("Referer",referer);try{int code=c.getResponseCode();if(code>=300&&code<400){url=Feeds.absolute(url,c.getHeaderField("Location"));continue;}if(code!=200&&code!=206)throw new IOException();try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;long end=System.currentTimeMillis()+6000;while((n=in.read(bytes))!=-1){if(System.currentTimeMillis()>end||!canLoad())throw new IOException("preview budget");int take=Math.min(n,max-out.size());out.write(bytes,0,take);if(out.size()>65536&&out.size()%65536<8192&&FlvPreview.find(out.toByteArray())!=null)break;if(out.size()>=max)break;}return out.toByteArray();}}finally{c.disconnect();}}throw new IOException();}
 Bitmap decode(byte[] bytes){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth<=0||bounds.outWidth>16000||bounds.outHeight>16000)return null;BitmapFactory.Options opts=new BitmapFactory.Options();opts.inSampleSize=Math.max(1,Math.max(bounds.outWidth/480,bounds.outHeight/270));opts.inPreferredConfig=Bitmap.Config.ARGB_8888;return scale(BitmapFactory.decodeByteArray(bytes,0,bytes.length,opts));}
 Bitmap scale(Bitmap b){if(b==null)return null;Bitmap small=Bitmap.createScaledBitmap(b,Ui.LEAN?288:320,Ui.LEAN?162:180,true);if(small!=b)b.recycle();return small;}
 void refreshViews(){for(Map.Entry<ImageView,Events.Group> e:new ArrayList<Map.Entry<ImageView,Events.Group>>(bound.entrySet()))if(e.getKey()!=null)bind(e.getKey(),e.getValue());}
 void clearViews(){waiting.clear();bound.clear();}
 void onReturn(){failed.clear();memory.evictAll();cachedAt.clear();}
 void close(){closed=true;workers.shutdownNow();waiting.clear();}
}
